// ── Runtime stubs (reject / no-op outside the Tauri shell) ──────────────────

function missing(name: string): () => Promise<never> {
  return () =>
    Promise.reject(
      new Error(`[bindings fallback] "${name}" needs the Tauri backend`),
    );
}

// Callee-side session bridge: the active source answers from its own
// calendar hook (a source file answering in the app's SymbolSession format).
async function bridgedSymbolSession(symbol: string): Promise<CommandResult<SymbolSession>> {
  try {
    // Static import string — bundled, no runtime cycle (only called, never
    // at module scope).
    const { source } = await import("./data/sources");
    const hook = source().symbolSessions;
    if (hook) return { status: "ok", data: await hook(symbol) };
  } catch {
    /* no hook or calendar unreachable — reject below like every command */
  }
  return missing("getSymbolSession")();
}

// Funding block: the active source answers direct, else the static mirror.
async function bridgedFundingStatus(): Promise<CommandResult<import("./data/funding").Funding | null>> {
  try {
    const { source } = await import("./data/sources");
    const hook = source().fundingStatus;
    if (hook) return { status: "ok", data: await hook() };
  } catch {
    /* hook failed — fall through to the mirror */
  }
  try {
    const { SAMPLE_FUNDING } = await import("./data/providers/sample");
    return { status: "ok", data: SAMPLE_FUNDING };
  } catch {
    /* unreachable — reject below like every command */
  }
  return missing("getFundingStatus")();
}

export const commands: {
  getSymbolSession(symbol: string): Promise<CommandResult<SymbolSession>>;
  getFundingStatus(): Promise<CommandResult<import("./data/funding").Funding | null>>;
  alertEngineClaim(): Promise<boolean>;
  alertEngineSet(rules: EngineRule[], grids: EngineGrid[]): Promise<unknown>;
  alertEngineInfo(): Promise<AlertEngineInfo>;
  getProxySettings(): Promise<ProxySettings>;
  setProxySettings(settings: ProxySettings): Promise<CommandResult<void>>;
  agentReady(): Promise<void>;
  agentServerStatus(): Promise<AgentServerStatus>;
  agentServerSetEnabled(enabled: boolean): Promise<CommandResult<AgentServerStatus>>;
  agentServerSetPort(port: number): Promise<CommandResult<AgentServerStatus>>;
  agentServerNewToken(): Promise<CommandResult<AgentServerStatus>>;
  agentReply(id: number, body: string): Promise<void>;
  assistantConfig(): Promise<AssistantConfig>;
  assistantSaveModel(input: AssistantModelInput): Promise<CommandResult<AssistantConfig>>;
  assistantRemoveModel(id: string): Promise<CommandResult<AssistantConfig>>;
  assistantSelect(id: string | null, effort: string | null): Promise<CommandResult<AssistantConfig>>;
  assistantListModels(baseUrl: string, key: string | null, id: string | null): Promise<CommandResult<string[]>>;
  assistantChat(request: number, body: string, onEvent: any): Promise<CommandResult<void>>;
  assistantCancel(request: number): Promise<void>;
  localModelInfo(): Promise<CommandResult<LocalModelInfo>>;
  localModelInstall(onProgress: any): Promise<CommandResult<void>>;
  localModelCancel(): Promise<void>;
  localModelRemove(): Promise<CommandResult<void>>;
  localSeriesList(): Promise<CommandResult<LocalSeries[]>>;
  localSeriesSave(meta: LocalSeries, rows: number[]): Promise<CommandResult<void>>;
  localSeriesRead(name: string): Promise<CommandResult<number[]>>;
  localSeriesDelete(name: string): Promise<CommandResult<void>>;
  localSeriesRename(from: string, target: string): Promise<CommandResult<void>>;
  localFolderScan(folder: string): Promise<CommandResult<FolderFile[]>>;
  localFolderRead(folder: string, file: string): Promise<CommandResult<string>>;
  getFundamentals(symbol: string): Promise<CommandResult<Fundamentals>>;
  getFilings(symbol: string, query: FilingQuery): Promise<CommandResult<FilingList>>;
  readFiling(symbol: string, accn: string, section: string | null, offset: number | null): Promise<CommandResult<FilingText>>;
  marketPassSet(pass: string | null, exp: number | null): void;
  marketPassResume(): void;
  [key: string]: any;
} = new Proxy(
  {},
  {
    get: (_t, prop: string) => {
      if (prop === "then") return undefined;
      if (prop === "getSymbolSession") return bridgedSymbolSession;
      if (prop === "getFundingStatus") return bridgedFundingStatus;
      return missing(String(prop));
    },
  },
) as {
  getSymbolSession(symbol: string): Promise<CommandResult<SymbolSession>>;
  getFundingStatus(): Promise<CommandResult<import("./data/funding").Funding | null>>;
  alertEngineClaim(): Promise<boolean>;
  alertEngineSet(rules: EngineRule[], grids: EngineGrid[]): Promise<unknown>;
  alertEngineInfo(): Promise<AlertEngineInfo>;
  getProxySettings(): Promise<ProxySettings>;
  setProxySettings(settings: ProxySettings): Promise<CommandResult<void>>;
  agentReady(): Promise<void>;
  agentServerStatus(): Promise<AgentServerStatus>;
  agentServerSetEnabled(enabled: boolean): Promise<CommandResult<AgentServerStatus>>;
  agentServerSetPort(port: number): Promise<CommandResult<AgentServerStatus>>;
  agentServerNewToken(): Promise<CommandResult<AgentServerStatus>>;
  agentReply(id: number, body: string): Promise<void>;
  assistantConfig(): Promise<AssistantConfig>;
  assistantSaveModel(input: AssistantModelInput): Promise<CommandResult<AssistantConfig>>;
  assistantRemoveModel(id: string): Promise<CommandResult<AssistantConfig>>;
  assistantSelect(id: string | null, effort: string | null): Promise<CommandResult<AssistantConfig>>;
  assistantListModels(baseUrl: string, key: string | null, id: string | null): Promise<CommandResult<string[]>>;
  assistantChat(request: number, body: string, onEvent: any): Promise<CommandResult<void>>;
  assistantCancel(request: number): Promise<void>;
  localModelInfo(): Promise<CommandResult<LocalModelInfo>>;
  localModelInstall(onProgress: any): Promise<CommandResult<void>>;
  localModelCancel(): Promise<void>;
  localModelRemove(): Promise<CommandResult<void>>;
  localSeriesList(): Promise<CommandResult<LocalSeries[]>>;
  localSeriesSave(meta: LocalSeries, rows: number[]): Promise<CommandResult<void>>;
  localSeriesRead(name: string): Promise<CommandResult<number[]>>;
  localSeriesDelete(name: string): Promise<CommandResult<void>>;
  localSeriesRename(from: string, target: string): Promise<CommandResult<void>>;
  localFolderScan(folder: string): Promise<CommandResult<FolderFile[]>>;
  localFolderRead(folder: string, file: string): Promise<CommandResult<string>>;
  getFundamentals(symbol: string): Promise<CommandResult<Fundamentals>>;
  getFilings(symbol: string, query: FilingQuery): Promise<CommandResult<FilingList>>;
  readFiling(symbol: string, accn: string, section: string | null, offset: number | null): Promise<CommandResult<FilingText>>;
  marketPassSet(pass: string | null, exp: number | null): void;
  marketPassResume(): void;
  [key: string]: any;
};

// Any `events.<anything>.listen(...)` resolves to a no-op unlisten handle.
export const events: any = new Proxy(
  {},
  {
    get: (_t, prop: string) => {
      if (prop === "then") return undefined;
      return { listen: () => Promise.resolve(() => {}) };
    },
  },
);
